// Shared by the ArrowLeft/ArrowRight keydown handler AND the footer's own
// prev/next paging buttons (Nutzerwunsch 2026-08-03: "Deren Funktion soll
// identisch mit der implementierten Pfeiltasten-Funktion sein") -- dir is -1
// (back) or +1 (forward) through the flat book order.
function pageBy(dir) {
  const domain = domainClassOf(document.body);
  const order = FLAT_ORDERS[domain ? domain.slice(7) : "genesys"] || [];
  const idx = order.indexOf(location.pathname);
  if (idx === -1) {
    // Not a flat-order page at all -- i.e. the domain's own home portal
    // (its URL isn't in the list, see FLAT_ORDER_URLS in build-site.js).
    // Forward from there has an obvious target: the domain's own first
    // article ("Introduction", order[0]) -- back has no obvious target
    // (nothing comes "before" the book even starts), so that's left a
    // no-op rather than guessed at.
    if (dir > 0 && order.length) navigate(order[0], true);
    return;
  }
  const targetIdx = idx + dir;
  if (targetIdx < 0 || targetIdx >= order.length) return;
  navigate(order[targetIdx], true);
}
document.addEventListener("keydown", function (e) {
  if (e.key !== "ArrowLeft" && e.key !== "ArrowRight") return;
  if (e.ctrlKey || e.metaKey || e.altKey || e.shiftKey) return;
  const active = document.activeElement;
  if (active && (active.tagName === "INPUT" || active.tagName === "TEXTAREA" || active.isContentEditable)) return;
  pageBy(e.key === "ArrowLeft" ? -1 : 1);
});
// ArrowUp/ArrowDown always scroll .content (Nutzerwunsch 2026-08-05: "egal
// ob Vollbildmodus oder nicht, immer Bildlauf in die entsprechende
// Richtung... Ausnahme falls der Fokus auf dem Suchfeld ist") -- .content is
// the one actually-scrolling box in both fullscreen and the normal layout
// alike (its own overflow-y: auto in site.scss is unconditional, not a
// fullscreen-only thing), so no branching on body.is-fullscreen is needed
// here. Explicit scrollBy() rather than relying on the browser's own native
// arrow-key scroll: that only fires when the CURRENTLY FOCUSED element's
// nearest scrollable ancestor happens to be .content, which isn't true right
// after e.g. a navbar button was clicked and kept focus. Same
// INPUT/TEXTAREA/isContentEditable guard as ArrowLeft/ArrowRight above --
// covers the search field, the one explicit exception named by the user.
// PageUp/PageDown (Nutzerwunsch 2026-08-05, corrected same day after a
// misread: NOT "same step as ArrowUp/ArrowDown" -- "egal wo der Cursor oder
// Fokus... gerade ist, so wirken, als sei auf dem Textbereich PageUp bzw.
// PageDown gedrückt worden", i.e. .content's own NATIVE PageUp/PageDown
// scroll amount -- a near-full-viewport jump, not the small arrow-key nudge)
// share the same guard/dispatch as ArrowUp/ArrowDown, but scroll by
// content.clientHeight instead of the fixed small step. "* 0.9", not the
// bare clientHeight, so the last couple lines of the previous screenful stay
// visible at the top of the next one for continuity -- the same convention
// browsers themselves use for a real PageUp/PageDown on a focused scroll
// container. Home/End (Nutzerwunsch 2026-08-05: "'Pos1' soll direkt an den
// Anfang... 'Ende' direkt ans Ende") jump straight to .content's own scroll
// boundaries instead of stepping.
const ARROW_SCROLL_AMOUNT = 80;
document.addEventListener("keydown", function (e) {
  if (e.key !== "ArrowUp" && e.key !== "ArrowDown" && e.key !== "PageUp" && e.key !== "PageDown" && e.key !== "Home" && e.key !== "End") return;
  if (e.ctrlKey || e.metaKey || e.altKey || e.shiftKey) return;
  const active = document.activeElement;
  if (active && (active.tagName === "INPUT" || active.tagName === "TEXTAREA" || active.isContentEditable)) return;
  const content = document.querySelector(".content");
  if (!content) return;
  e.preventDefault();
  if (e.key === "Home") { content.scrollTo({ top: 0, behavior: "smooth" }); return; }
  if (e.key === "End") { content.scrollTo({ top: content.scrollHeight, behavior: "smooth" }); return; }
  const dir = (e.key === "ArrowDown" || e.key === "PageDown") ? 1 : -1;
  const amount = (e.key === "PageUp" || e.key === "PageDown") ? content.clientHeight * 0.9 : ARROW_SCROLL_AMOUNT;
  content.scrollBy({ top: dir * amount, behavior: "smooth" });
});
// Alt+Shift+F clears and focuses the search bar (Nutzerwunsch 2026-08-05).
// Works regardless of what currently has focus -- unlike the other single-
// key shortcuts above, this one is explicitly MEANT to work while some other
// field/element has focus (that's the whole point, a fast way to jump into
// search from anywhere), so it has no INPUT/TEXTAREA guard.
document.addEventListener("keydown", function (e) {
  if (e.key.toLowerCase() !== "f") return;
  if (!e.altKey || !e.shiftKey || e.ctrlKey || e.metaKey) return;
  const input = document.querySelector(".search-input");
  if (!input) return;
  e.preventDefault();
  input.value = "";
  input.dispatchEvent(new Event("input", { bubbles: true }));
  input.focus();
});
// Delegated on document (not bound to the buttons themselves) so it keeps
// working after a client-side navigation replaces the footer's innerHTML
// wholesale (see swapContent's #page-footer-nav handling above) -- same
// pattern as the generic <a> click interceptor and the sidebar toggle logic.
document.addEventListener("click", function (e) {
  const btn = e.target.closest(".footer-nav-prev, .footer-nav-next");
  if (!btn) return;
  pageBy(btn.classList.contains("footer-nav-prev") ? -1 : 1);
});

