(function () {
  const input = document.querySelector(".search-input");
  const results = document.querySelector(".search-results");
  if (!input || !results) return;

  function escapeHtml(s) {
    return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  // -1 = nothing highlighted yet (plain hover/Enter-picks-first still
  // works); ArrowDown/ArrowUp move a "active" class among the result <a>
  // tags without touching input focus, mirroring a standard combobox.
  let activeIndex = -1;

  function setActive(idx) {
    const items = Array.from(results.querySelectorAll(".search-result-item"));
    if (!items.length) return;
    activeIndex = Math.max(0, Math.min(idx, items.length - 1));
    items.forEach((el, i) => el.classList.toggle("active", i === activeIndex));
    items[activeIndex].scrollIntoView({ block: "nearest" });
  }

  // Live path-shortening (Nutzerwunsch 2026-08-04): every result's path
  // segments (see breadcrumbSegments in build-site.js) carry an "alias" flag
  // -- a hard-coded abbreviation (book/chapter/section short name) that must
  // never be dropped, vs. a generic truncated real title that's fair game.
  // Default display depth for every result is JUST its alias prefix (as
  // short as the rule ever allows, unique or not -- "bei EINDEUTIGEN
  // Treffern wird der Pfad immer so weit wie erlaubt gekürzt"). Only if that
  // default collides with another CURRENTLY shown result -- same title AND
  // same shortened path -- do the colliding entries grow one segment at a
  // time (repeating until no collision remains or the full path is reached)
  // to disambiguate. Recomputed fresh on every keystroke since "currently
  // shown" depends entirely on the live query's result set.
  function shortenPaths(matches) {
    const depth = matches.map((m) => {
      let n = 0;
      while (n < m.pathSegs.length && m.pathSegs[n].alias) n++;
      return n;
    });
    function pathTextAt(i) {
      return matches[i].pathSegs.slice(0, depth[i]).map((s) => s.text).join("›");
    }
    function collides(i) {
      const key = matches[i].title + "␀" + pathTextAt(i);
      for (let j = 0; j < matches.length; j++) {
        if (j !== i && matches[j].title + "␀" + pathTextAt(j) === key) return true;
      }
      return false;
    }
    let changed = true;
    while (changed) {
      changed = false;
      for (let i = 0; i < matches.length; i++) {
        if (depth[i] < matches[i].pathSegs.length && collides(i)) {
          depth[i]++;
          changed = true;
        }
      }
    }
    return matches.map((m, i) => pathTextAt(i));
  }

  function render(query) {
    const q = query.trim().toLowerCase();
    activeIndex = -1;
    if (!q) {
      results.hidden = true;
      results.innerHTML = "";
      results.style.width = "";
      return;
    }
    // Domain is the OUTERMOST grouping (Nutzerwunsch 2026-08-04, correcting
    // the previous same-day instruction: "natürlich soll hierbei zuallerst
    // nach Domäne sortiert werden, mach zuerst alle GC-Treffer, dann alle
    // RoT-Treffer") -- ALL Genesys hits before ANY Terrinoth hit, full stop,
    // not just as a tiebreaker within a relevance tier. Relevance tier
    // (exact-prefix vs. mid-title) and natural document order (sortKey) are
    // still applied, but now nested one level deeper, inside each domain
    // group. sortKey's own leading "0."/"1." domain-rank digit (see
    // sortKeyFor in build-site.js) is reused directly as the domain split.
    const startsGC = [], containsGC = [], startsRoT = [], containsRoT = [];
    for (const item of SEARCH_INDEX) {
      const i = item.title.toLowerCase().indexOf(q);
      if (i === -1) continue;
      const isGC = item.sortKey.charAt(0) === "0";
      (i === 0 ? (isGC ? startsGC : startsRoT) : (isGC ? containsGC : containsRoT)).push(item);
    }
    const bySortKey = (a, b) => (a.sortKey < b.sortKey ? -1 : a.sortKey > b.sortKey ? 1 : 0);
    [startsGC, containsGC, startsRoT, containsRoT].forEach((arr) => arr.sort(bySortKey));
    // Domain outermost, THEN tier -- GC-starts, GC-contains, RoT-starts,
    // RoT-contains, not the tier-outer/domain-inner grouping an earlier
    // attempt at this concat order would produce. No hard cap anymore
    // (Nutzerwunsch 2026-08-04: "Scrollliste einfach nur so lang wie nötig
    // machen") -- the old .slice(0, 15) cut the list off BEFORE
    // .search-results' own scrolling (max-height: 60vh; overflow-y: auto,
    // see site.scss) ever got a chance to kick in, so a broad query with 15+
    // Genesys hits silently dropped every Terrinoth hit entirely instead of
    // just requiring a scroll to reach them.
    const matches = startsGC.concat(containsGC, startsRoT, containsRoT);
    if (!matches.length) {
      results.innerHTML = '<div class="search-no-results">No matches</div>';
      results.style.width = "";
      results.hidden = false;
      return;
    }
    const shortPaths = shortenPaths(matches);
    // Each hit rendered in its OWN domain's body font (Nutzerwunsch
    // 2026-08-04: "schreibe die GC-Treffer in GC-Font, die RoT-Treffer in
    // RoT-Font"), not the current page's -- a GC hit stays GC-styled even
    // while searching from a Terrinoth page, and vice versa. Same "Adobe
    // Hebrew Regular"/"Garamond Premier Pro" @font-face names the domains'
    // own body text already uses (see body.domain-genesys/domain-terrinoth
    // in site.scss); .search-result-gc/-rot just apply the matching one
    // here, keyed off the same sortKey domain-rank digit used for sorting.
    results.innerHTML = matches
      .map((m, i) => '<a class="search-result-item ' + (m.sortKey.charAt(0) === "0" ? "search-result-gc" : "search-result-rot") + '" href="' + m.url + '"><span class="search-result-title">' + m.titleHtml + '</span><span class="search-result-path">' + escapeHtml(shortPaths[i]) + "</span></a>")
      .join("");
    results.hidden = false;
    // Reset back to the base CSS's own "width: max-content" BEFORE
    // measuring (Nutzerwunsch 2026-08-04 bug, found while chasing "zu viel
    // Platz"): every keystroke re-runs render(), but the PREVIOUS
    // keystroke's inline width (set at the end of this same function) was
    // still sitting on the element going into the next measurement pass.
    // .search-result-title's "flex: 1 1 auto" genuinely shrinks to fit
    // inside whatever width the ancestor already has -- unlike overflow:
    // hidden clipping, which scrollWidth ignores, a real flex-shrink
    // changes the element's actual laid-out size, so scrollWidth measured
    // against a stale, too-narrow-or-too-wide leftover width no longer
    // reflects the new content's true natural size.
    results.style.width = "";
    // Width = widest title + widest path (Nutzerwunsch 2026-08-04, repeated
    // emphatically: "SO BREIT WIE DER BREITESTE TREFFER + SO BREIT WIE DER
    // BREITESTE PFAD"), each measured independently -- NOT the widest single
    // ROW's own title+path combined, which is a different (and often
    // smaller) number whenever the widest title and the widest path belong
    // to different rows. scrollWidth reports each span's true content width
    // regardless of its own overflow:hidden/ellipsis clipping, so no need to
    // temporarily un-clip anything to measure it.
    // ONLY rows actually visible without scrolling count (Nutzerwunsch
    // 2026-08-04, follow-up after removing the old 15-result cap made the
    // box far too wide): shortenPaths' own collision-avoidance above still
    // correctly runs against the FULL, now much longer match list -- paths
    // stay genuinely unique even once you scroll further down -- but a
    // title/path belonging to some far-down row nobody can even see yet
    // (already clipped by .search-results' own max-height/overflow-y, see
    // site.scss) shouldn't be allowed to force the box wider than what's
    // actually on screen. results.clientHeight already reflects that clip
    // at this exact point, before this element's own width is touched.
    let maxTitle = 0;
    let maxPath = 0;
    const visibleBottom = results.clientHeight;
    results.querySelectorAll(".search-result-item").forEach((item) => {
      if (item.offsetTop + item.offsetHeight > visibleBottom) return;
      maxTitle = Math.max(maxTitle, item.querySelector(".search-result-title").scrollWidth);
      maxPath = Math.max(maxPath, item.querySelector(".search-result-path").scrollWidth);
    });
    // +12 (.search-result-item's own gap) +20 (its 10px+10px horizontal
    // padding) +2 (.search-results' own 1px+1px border) -- see site.scss.
    results.style.width = (maxTitle + maxPath + 12 + 20 + 2) + "px";
  }

  input.addEventListener("input", function () { render(input.value); });
  input.addEventListener("focus", function () { if (input.value) render(input.value); });
  input.addEventListener("keydown", function (e) {
    if (e.key === "Escape") { results.hidden = true; input.blur(); return; }
    if (e.key === "ArrowDown") { e.preventDefault(); setActive(activeIndex + 1); return; }
    if (e.key === "ArrowUp") { e.preventDefault(); setActive(activeIndex - 1); return; }
    if (e.key === "Enter") {
      const items = results.querySelectorAll(".search-result-item");
      const pick = activeIndex >= 0 ? items[activeIndex] : items[0];
      if (pick) pick.click();
    }
  });
  // Clears the field once a result is actually followed -- both a mouse
  // click and the Enter-key handler above end up dispatching a real click
  // on the result <a>, so this single listener covers both.
  // Also drops focus out of the field (Nutzerwunsch 2026-08-05: "nachdem man
  // im Suchfeld Enter gedrückt... oder einen Treffer... geklickt oder
  // geentert hat, soll der Fokus aus dem Suchfeld entfernt werden") -- both
  // paths (mouse click on a result, or Enter which dispatches a synthetic
  // click on the active/first result, see the input's own keydown handler
  // above) end up here, so one blur() covers both.
  results.addEventListener("click", function () {
    input.value = "";
    results.hidden = true;
    results.innerHTML = "";
    input.blur();
  });
  document.addEventListener("click", function (e) {
    if (!e.target.closest(".navbar-search")) results.hidden = true;
  });
})();

// ---- Cookie helpers (Nutzerwunsch 2026-07-30, explicit and emphatic:
// persistence for theme/language/font-size is cookie-based, not
// localStorage) -- 1-year expiry, path=/ so every page under the domain
// reads the same cookie regardless of which article set it.
const COOKIE_MAX_AGE = 60 * 60 * 24 * 365;
function setCookie(name, value) {
  document.cookie = name + "=" + encodeURIComponent(value) + "; path=/; max-age=" + COOKIE_MAX_AGE + "; SameSite=Lax";
}
function getCookie(name) {
  const m = document.cookie.match("(?:^|; )" + name + "=([^;]*)");
  return m ? decodeURIComponent(m[1]) : null;
}

// Light/dark toggle (top-right glyph button). The initial theme is already
// applied by the inline script right after <body> (see pageShell) -- before
// this file even loads -- so all that's left here is reacting to clicks.
// The domain switch (top-left logos) needs no dedicated handler of its own
// -- it's a real link now (see HOME_URLS in build-site.js), handled by the
// generic click listener above like any other nav link.
const THEME_STORAGE_KEY = "theme";
// querySelectorAll, not querySelector (Nutzerwunsch 2026-08-04, fullscreen
// mode): there are now TWO ".theme-toggle" buttons in the DOM -- the
// navbar's own, and .fullscreen-bar's copy (see pageShell in build-site.js)
// -- both need the exact same click behavior, and since the resulting
// body.theme-* class is what actually drives BOTH buttons' visual state via
// CSS, no extra sync logic is needed beyond just wiring up every instance.
// Tooltip text names the ACTION a click performs, not the current state
// (Nutzerwunsch 2026-08-05: "Set dark mode" bzw. "Set light mode") -- so it
// has to flip in step with the theme itself, both right after a click AND
// on initial page load (a page can load in either theme depending on the
// saved cookie, see the inline pre-body script in pageShell).
function updateThemeToggleTitles() {
  const title = document.body.classList.contains("theme-dark") ? "Set light mode" : "Set dark mode";
  document.querySelectorAll(".theme-toggle").forEach(function (el) { el.title = title; });
}
updateThemeToggleTitles();
document.querySelectorAll(".theme-toggle").forEach(function (themeToggle) {
  themeToggle.addEventListener("click", function () {
    const next = document.body.classList.contains("theme-dark") ? "light" : "dark";
    document.body.classList.remove("theme-light", "theme-dark");
    document.body.classList.add("theme-" + next);
    setCookie(THEME_STORAGE_KEY, next);
    updateThemeToggleTitles();
  });
});

// Language toggle (placeholder, Nutzerwunsch 2026-07-29): purely cosmetic
// for now -- there's no German content to actually switch to yet, so a
// click just swaps the flag glyph and nothing else. Defaults to the German
// flag (see the button's initial content in build-site.js's pageShell)
// since it represents "switch TO this language", and the site's actual
// content is all English already -- no persistence, since there's no real
// state behind it to remember yet (once real German content exists, this
// gets the same cookie treatment as theme/font-scale).
const langToggle = document.querySelector(".lang-toggle");
if (langToggle) {
  langToggle.addEventListener("click", function () {
    langToggle.textContent = langToggle.textContent === "🇩🇪" ? "🇺🇸" : "🇩🇪";
  });
}

// Floating overlay layout toggle (Nutzerwunsch 2026-07-31): one central
// button, not per-container -- swaps .filetree-sidebar/.navbar/.page-footer-
// nav from their normal fixed layout into edge-anchored overlays that slide
// in on hover (see body.layout-floating in site.scss). Persisted the same
// way as theme/fontScale; the inline pre-body script (pageShell) applies it
// before first paint to avoid a flash of the wrong layout.
const layoutToggle = document.querySelector(".layout-toggle");
if (layoutToggle) {
  layoutToggle.addEventListener("click", function () {
    const next = !document.body.classList.contains("layout-floating");
    document.body.classList.toggle("layout-floating", next);
    setCookie("layoutFloating", next ? "1" : "0");
  });
}

// Site-wide font-size buttons (Nutzerwunsch 2026-07-30): every content
// font-size in site.scss is expressed in em/pt-on-top-of-em relative to
// body's own font-size, so scaling just that one root value scales the
// whole site proportionally (headings, tables, lists) while leaving the
// small fixed pt calibration offsets -- see the .domain-genesys/.domain-
// terrinoth h1-h6 formulas -- essentially untouched, which is what keeps
// them working as font-family size compensation instead of also scaling.
// --font-scale is applied as an inline style (not a class) so it can hold
// an arbitrary numeric value; the initial value is set by the same inline
// pre-body script that applies the theme (see pageShell), to avoid a
// flash of default-sized text before this file loads.
// FONT_SCALE_KEY is the NORMAL-mode cookie -- kept as the original,
// pre-fullscreen name so an existing saved preference survives this change
// unchanged. Fullscreen gets its own SEPARATE cookie (Nutzerwunsch
// 2026-08-05: "Cookiedaten hinzufügen, die für Normalmodus und Vollbildmodus
// speichern, welche Textgröße eingestellt war... wird also nicht dieselbe
// Größe bzw. die Maximalgröße des Normalmodus angewendet, sondern einfach
// der zuvor für Normalmodus gespeicherte Wert" -- REGRESS 2026-08-05: the
// original single-cookie design read/wrote the SAME cookie for both modes,
// so leaving fullscreen didn't restore the user's separate normal-mode
// preference, it clobbered it with the (clamped-down) fullscreen value).
// fontScaleKeyActive()/fontScaleMaxActive() are functions, not cached
// variables, reading body.is-fullscreen fresh on every call -- simpler and
// less error-prone than a manually-synced "let" that has to be remembered
// on every fullscreenchange.
const FONT_SCALE_KEY = "fontScale";
const FONT_SCALE_KEY_FULLSCREEN = "fontScaleFullscreen";
// Stream-Modus's own cookie (Nutzerwunsch 2026-08-05) -- shared between the
// article-level stream mode AND a popover put into stream mode (see
// enterPopoverStreamMode below): "die Schriftgröße des Stream-Modus
// annehmen" for the popover case means literally the SAME stored value, not
// an independent one, so a size change made from inside a stream-mode
// popover also carries over to the article once the popover closes, and
// vice versa.
const FONT_SCALE_KEY_STREAM = "fontScaleStream";
// FONT_SCALE_MIN lowered from 0.8 to 0.6 (Nutzerwunsch 2026-07-31: "Minus
// soll noch zwei Stufen kleiner möglich sein") -- two more FONT_SCALE_STEPs
// below the old floor. Keep in sync with the hardcoded 0.6 in the inline
// pre-body FOUC-prevention script below (pageShell), which duplicates this
// clamp before this script has even loaded.
const FONT_SCALE_MIN = 0.6;
const FONT_SCALE_MAX = 1.4;
const FONT_SCALE_STEP = 0.1;
// Fullscreen's own ceiling is double the normal one (Nutzerwunsch
// 2026-08-04: "im Vollbildmodus kann man die Schrift nochmal deutlich
// größer machen... der Max-Wert wird im Vollbildmodus verdoppelt").
const FONT_SCALE_MAX_FULLSCREEN = FONT_SCALE_MAX * 2;
// Stream-Modus bounds/step -- REVISED 2026-08-05, same day: the original
// 3x/21x/step-2.0 values ("waren unsinnig" per the user's own correction)
// are replaced with 2x/8x, step further reduced same day from 0.5 to 0.2 for
// finer control. Same --font-scale multiplier this whole system already
// uses everywhere else, just a bigger range than normal/fullscreen, since
// Stream-Modus is built for reading from across a room/stream viewers, not a
// normal screen distance.
const FONT_SCALE_MIN_STREAM = 2;
const FONT_SCALE_MAX_STREAM = 8;
const FONT_SCALE_STEP_STREAM = 0.2;
function isStreamModeActive() {
  return document.body.classList.contains("stream-mode") || document.body.classList.contains("popover-stream-mode");
}
function fontScaleKeyActive() {
  if (isStreamModeActive()) return FONT_SCALE_KEY_STREAM;
  return document.body.classList.contains("is-fullscreen") ? FONT_SCALE_KEY_FULLSCREEN : FONT_SCALE_KEY;
}
function fontScaleMinActive() {
  return isStreamModeActive() ? FONT_SCALE_MIN_STREAM : FONT_SCALE_MIN;
}
function fontScaleMaxActive() {
  if (isStreamModeActive()) return FONT_SCALE_MAX_STREAM;
  return document.body.classList.contains("is-fullscreen") ? FONT_SCALE_MAX_FULLSCREEN : FONT_SCALE_MAX;
}
function fontScaleStepActive() {
  return isStreamModeActive() ? FONT_SCALE_STEP_STREAM : FONT_SCALE_STEP;
}
function getFontScale() {
  const v = parseFloat(getCookie(fontScaleKeyActive()));
  // No cookie at all -> the mode's own floor (Stream-Modus has no sensible
  // "1" default, unlike normal/fullscreen -- see fontScaleMinActive) rather
  // than the OTHER modes' shared "no cookie yet" default of 1, which sits
  // far outside Stream-Modus's own [3,21] range entirely.
  if (!v) return fontScaleMinActive();
  return Math.min(fontScaleMaxActive(), Math.max(fontScaleMinActive(), v));
}
function setFontScale(v) {
  const clamped = Math.min(fontScaleMaxActive(), Math.max(fontScaleMinActive(), v)).toFixed(2);
  document.documentElement.style.setProperty("--font-scale", clamped);
  setCookie(fontScaleKeyActive(), clamped);
}
// querySelectorAll, not querySelector (Nutzerwunsch 2026-08-04, fullscreen
// mode) -- same reasoning as .theme-toggle above: .fullscreen-bar carries
// its own copy of each button, both wired up identically here. Stream-Modus
// has no buttons of its own at all ("es gibt keine sonstigen Elemente") --
// see the global "+"/"-" keydown handler further down instead.
const fontDecreaseBtns = document.querySelectorAll(".font-decrease");
const fontIncreaseBtns = document.querySelectorAll(".font-increase");
// Disable +/- at their respective limits (Nutzerwunsch 2026-07-31) -- run
// once on load (cookie may already be at a limit) and again after every
// click, since setFontScale's own clamp is what actually decides whether a
// click moved the value at all. Also re-run on every fullscreen enter/exit
// (fontScaleMaxActive() itself now reads a different cookie/ceiling).
function updateFontButtonState() {
  const scale = getFontScale();
  fontDecreaseBtns.forEach(function (b) { b.disabled = scale <= fontScaleMinActive(); });
  fontIncreaseBtns.forEach(function (b) { b.disabled = scale >= fontScaleMaxActive(); });
}
updateFontButtonState();
fontDecreaseBtns.forEach(function (b) { b.addEventListener("click", function () { setFontScale(getFontScale() - fontScaleStepActive()); updateFontButtonState(); }); });
fontIncreaseBtns.forEach(function (b) { b.addEventListener("click", function () { setFontScale(getFontScale() + fontScaleStepActive()); updateFontButtonState(); }); });
// "+"/"-" as KEYBOARD shortcuts, in every mode (Nutzerwunsch 2026-08-05:
// "die Regelung, dass die + und - Button die Textgröße ändern, soll ab
// jetzt in jedem Modus gelten") -- the actual buttons already cover normal/
// fullscreen via the click handlers above; this is what makes it reachable
// in Stream-Modus too, which has no buttons at all. fontScaleStepActive()
// already resolves to the right step size (2.0 in Stream-Modus, 0.1
// otherwise) purely from body's current classes, same as every other
// mode-aware font-scale function here.
document.addEventListener("keydown", function (e) {
  if (e.key !== "+" && e.key !== "-") return;
  const active = document.activeElement;
  if (active && (active.tagName === "INPUT" || active.tagName === "TEXTAREA" || active.isContentEditable)) return;
  e.preventDefault();
  setFontScale(getFontScale() + (e.key === "+" ? 1 : -1) * fontScaleStepActive());
  updateFontButtonState();
});

// ---- Fullscreen mode (Nutzerwunsch 2026-08-04) ----
// requestFullscreen/exitFullscreen are the only JS-driven part; everything
// visual (hiding the sidebar/navbar/footer, the 10vw/10vh content margin,
// showing .fullscreen-bar/.fullscreen-page) is pure CSS keyed off
// body.is-fullscreen, kept in sync here via the "fullscreenchange" event
// rather than directly in the click handlers below -- fullscreen can also
// be exited by the browser itself (Esc key, F11, etc.), which fires
// "fullscreenchange" but never runs .fullscreen-close's own click handler,
// so this is the only place that's guaranteed to run on every transition
// either direction.
document.querySelectorAll(".fullscreen-toggle").forEach(function (btn) {
  btn.addEventListener("click", function () { document.documentElement.requestFullscreen(); });
});
document.querySelectorAll(".fullscreen-close").forEach(function (btn) {
  btn.addEventListener("click", function () { document.exitFullscreen(); });
});
// "f" toggles fullscreen on/off (Nutzerwunsch 2026-08-05: "sofern das
// Searchfeld nicht den Fokus hat") -- same INPUT/TEXTAREA/isContentEditable
// guard as the other single-key shortcuts above.
document.addEventListener("keydown", function (e) {
  if (e.key.toLowerCase() !== "f") return;
  // Not e.shiftKey too, unlike the other single-key shortcuts above --
  // Shift+f is how a capital "F" is typed and should still toggle, only
  // Ctrl/Cmd/Alt+f (browser/OS shortcuts, e.g. "Find") are left alone.
  if (e.ctrlKey || e.metaKey || e.altKey) return;
  const active = document.activeElement;
  if (active && (active.tagName === "INPUT" || active.tagName === "TEXTAREA" || active.isContentEditable)) return;
  if (document.fullscreenElement) document.exitFullscreen();
  else document.documentElement.requestFullscreen();
});
// Drives the cursor-hidden EXCEPTION for articles containing ANY collapsible
// "Hamburger-Menü" section (Nutzerwunsch 2026-08-05: "auf Artikeln, in denen
// es Container gibt, muss der Cursor sichtbar sein"; REGRESS 2026-08-05,
// caught same day: ".container-accordion-section" alone only matches the
// relocatable Infobox/Example/Table containers -- it missed the far more
// common PLAIN ".accordion-section" (see makeAccordionSection in
// build-site.js, class="accordion-section" with no "container-" prefix),
// the user's own "Hamburger-Menü" term for any ordinary fold/unfold section
// within an article's regular flow. Every ".container-accordion-section"
// element already carries ".accordion-section" too -- see
// extractRelocatableContainers's own class="accordion-section
// container-accordion-section" -- so the plain, broader class alone already
// covers both kinds, no need to check for either specifically.
// A plain JS-set body class, not CSS ":has(.accordion-section)" directly
// (tried first, REGRESS 2026-08-05: didn't reliably take effect) -- this
// sidesteps any doubt about :has() support/behavior entirely and matches
// the same "drive it off one JS-controlled class" pattern body.is-fullscreen
// itself already uses (see comment above). Has to re-run after every
// client-side navigation too (see swapContent below), not just on
// fullscreenchange -- a different article can load, with or without a
// collapsible section, while already in fullscreen.
function updateFullscreenContainerFlag() {
  // Also true on the Mennara map page (Nutzerwunsch 2026-08-07: "natürlich
  // muss der Mauszeiger im Vollbildmodus zu sehen sein") -- same class,
  // same underlying reason (fullscreen's own cursor: none would otherwise
  // hide the very cursor the hover interaction depends on), see .has-container
  // in site.scss.
  document.body.classList.toggle("has-container", !!document.querySelector(".content .accordion-section, .content .mennara-map"));
}
document.addEventListener("fullscreenchange", function () {
  const isFullscreen = !!document.fullscreenElement;
  // Stream-Modus now also drives the real Fullscreen API (Nutzerwunsch
  // 2026-08-05, see enterStreamFullscreen/exitStreamFullscreen further
  // down) -- while it's active, this listener must NOT also flip on
  // body.is-fullscreen, which would layer the separate Vollbildmodus UI
  // (its own cursor: none, .fullscreen-bar, 10vh/10vw content margin) on
  // top of Stream-Modus's own deliberately different look. isStreamModeActive
  // is defined further down in this file but already hoisted (function
  // declaration), so it's safe to call from here.
  if (!isStreamModeActive()) {
    document.body.classList.toggle("is-fullscreen", isFullscreen);
  }
  updateFullscreenContainerFlag();
  // REGRESS 2026-08-05, fixed: this used to hand-assign a module-level
  // "fontScaleMaxActive" variable here -- stale leftover from BEFORE
  // fontScaleKeyActive()/fontScaleMaxActive() became live functions that
  // read body.is-fullscreen (just toggled above) directly, on every call.
  // Left in place, it silently overwrote the FUNCTION binding with a plain
  // number, so the very next getFontScale()/setFontScale() call below threw
  // "fontScaleMaxActive is not a function" -- which in turn aborted this
  // whole handler, and (observed while testing) somehow left fullscreen
  // itself in a broken half-entered state. Nothing to do here now: reading
  // getFontScale() (whose OWN internal fontScaleMaxActive() call already
  // sees the class toggled two lines up) and writing it straight back via
  // setFontScale() is what actually persists the mode-appropriate value
  // into --font-scale and the (now separate per-mode, see
  // FONT_SCALE_KEY_FULLSCREEN) cookie.
  setFontScale(getFontScale());
  updateFontButtonState();
});
// Prev/next paging circles at the left/right screen edges (Nutzerwunsch
// 2026-08-04) -- same book-order paging as the footer buttons/ArrowLeft-
// ArrowRight (see pageBy above), just reachable without the footer that's
// hidden in fullscreen.
// The clickable/hoverable zone was enlarged 2026-08-05 to cover the whole
// side margin at .content's own height, not just the small 5vw circle (see
// .fullscreen-page in site.scss) -- on a touch device that zone should also
// forward a vertical swipe to .content's own scroll (Nutzerwunsch
// 2026-08-05: "nach oben oder nach unten wischen soll in diesen
// Seitenbereichen genauso wirken, als würde man auf dem Textfeld nach oben
// oder unten wischen"). .fullscreen-page is a position: fixed SIBLING of
// .content (see pageShell), not a descendant, so a native touch-scroll
// gesture landing on it has no scrollable ancestor to reach on its own --
// this replays the same drag manually via .content.scrollBy(). A genuine
// drag also has to suppress the synthetic "click" the browser still fires
// on touchend, or a swipe-to-scroll would ALSO trigger pageBy() as if it had
// been a tap.
let fullscreenPageSwiped = false;
document.querySelectorAll(".fullscreen-page").forEach(function (btn) {
  let lastY = null;
  let moved = false;
  btn.addEventListener("touchstart", function (e) {
    if (e.touches.length !== 1) return;
    lastY = e.touches[0].clientY;
    moved = false;
  }, { passive: true });
  btn.addEventListener("touchmove", function (e) {
    if (lastY === null || e.touches.length !== 1) return;
    const y = e.touches[0].clientY;
    const dy = lastY - y;
    lastY = y;
    if (Math.abs(dy) > 2) moved = true;
    const content = document.querySelector(".content");
    if (content) content.scrollBy({ top: dy });
  }, { passive: true });
  btn.addEventListener("touchend", function () {
    if (moved) fullscreenPageSwiped = true;
    lastY = null;
  });
});
document.querySelectorAll(".fullscreen-page-prev").forEach(function (btn) { btn.addEventListener("click", function () { if (fullscreenPageSwiped) { fullscreenPageSwiped = false; return; } pageBy(-1); }); });
document.querySelectorAll(".fullscreen-page-next").forEach(function (btn) { btn.addEventListener("click", function () { if (fullscreenPageSwiped) { fullscreenPageSwiped = false; return; } pageBy(1); }); });

// ---- Stream-Modus (Nutzerwunsch 2026-08-05) ----
// A separate, even more minimal mode than fullscreen ("noch krasser als der
// Vollbildmodus") -- entered ONLY via Ctrl+Alt+W (no button, no other
// trigger), left ONLY via Escape. Purely a body-class-driven CSS mode (see
// body.stream-mode in site.scss) -- deliberately does NOT touch the
// Fullscreen API at all, unlike .is-fullscreen; the two can coexist, and
// where they visually conflict (e.g. .content's own margin) stream-mode's
// own CSS rules win (see their source order in site.scss).
//
// The window-TITLE swap (Nutzerwunsch 2026-08-05) exists purely for OBS
// Studio's own Window Capture source, which is configured there to match
// the exact title "firefox.exe: Genesys&Terrinoth" -- so the capture only
// ever shows the browser while genuinely in Stream-Modus (article or
// popover), never fullscreen/normal/any other page. A single saved-title
// variable covers both the article and popover entry points (they're
// mutually exclusive per Ctrl+Alt+W's own dispatch below, so only one is
// ever "open" needing a title to restore at a time).
// Real browser Fullscreen, same as the "f" Vollbildmodus toggle above
// (Nutzerwunsch 2026-08-05: "Im Stream-Modus kommt kein echtes Vollbild...
// soll ebenso wie im Vollbildmodus auf echtes Vollbild umstellen") -- unlike
// the original design (see the removed comment on isStreamModeActive below),
// Stream-Modus DOES now touch the Fullscreen API, it just never sets
// body.is-fullscreen itself (guarded in the "fullscreenchange" listener
// above) so its own, deliberately different CSS stays in effect instead of
// Vollbildmodus's. is-fullscreen is force-removed here too, in case the user
// was already in true Vollbildmodus (its own "f" toggle) before entering
// Stream-Modus via Ctrl+Alt+W -- otherwise that stale class (added by an
// EARLIER fullscreenchange, before this guard could apply) would linger and
// still show cursor:none/the fullscreen-bar underneath. requestFullscreen's
// promise rejection (e.g. a user gesture requirement not met) is swallowed:
// Stream-Modus's own CSS mode still works perfectly well without real
// fullscreen, this is purely an enhancement on top.
function enterStreamFullscreen() {
  document.body.classList.remove("is-fullscreen");
  if (!document.fullscreenElement) {
    document.documentElement.requestFullscreen().catch(function () {});
  }
}
function exitStreamFullscreen() {
  if (document.fullscreenElement) document.exitFullscreen().catch(function () {});
}

let streamModeSavedTitle = null;
function enterStreamTitle() {
  if (streamModeSavedTitle === null) streamModeSavedTitle = document.title;
  document.title = "Genesys&Terrinoth";
}
function exitStreamTitle() {
  if (streamModeSavedTitle !== null) {
    document.title = streamModeSavedTitle;
    streamModeSavedTitle = null;
  }
}

// Infoboxes/Examples auto-expand in article-level Stream-Modus (Nutzerwunsch
// 2026-08-05: "Infoboxen und Examples werden automatisch aufgeklappt") --
// Tables need no such handling: their own <table> content is hidden by CSS
// regardless of the surrounding <details>'s open/closed state (see
// body.stream-mode in site.scss), so forcing them open would only ever
// reveal an empty shell for no benefit. Only containers that were NOT
// already open get force-opened, and only those get closed again on exit --
// one a user had already opened by hand before entering stays open
// afterwards too, exactly as they left it.
let streamModeOpenedContainers = [];
// Split out from enterArticleStreamMode (Nutzerwunsch 2026-08-05 gap found
// while implementing: a client-side navigation to a different article WHILE
// already in Stream-Modus -- clicking a link, ArrowLeft/ArrowRight paging --
// swaps in a whole new .content via swapContent, whose OWN Infobox/Example
// containers never got the initial force-open pass at all) -- called both
// on entry and again from swapContent below whenever it lands while
// body.stream-mode is already set.
function applyStreamModeAutoOpen() {
  document.querySelectorAll('.content details[data-kind="infobox"], .content details[data-kind="example"]').forEach(function (el) {
    if (!el.open) {
      el.open = true;
      streamModeOpenedContainers.push(el);
    }
  });
}
function enterArticleStreamMode() {
  document.body.classList.add("stream-mode");
  enterStreamTitle();
  enterStreamFullscreen();
  streamModeOpenedContainers = [];
  applyStreamModeAutoOpen();
  // --font-scale itself doesn't change just because a class was toggled --
  // it's a CSS custom property holding whatever number the LAST mode wrote
  // there, and stays exactly that until something calls setFontScale()
  // again. Without this, entering Stream-Modus would apply its 8px-margin
  // layout immediately but keep rendering text at the previous mode's own
  // (far smaller) --font-scale value until the user happened to press "+"/
  // "-" for the first time. getFontScale() already resolves against the
  // classes just added above, so this immediately snaps to the correct
  // Stream-Modus value (or its floor, on first use).
  setFontScale(getFontScale());
  updateFontButtonState();
}
function exitArticleStreamMode() {
  document.body.classList.remove("stream-mode");
  exitStreamTitle();
  exitStreamFullscreen();
  streamModeOpenedContainers.forEach(function (el) { el.open = false; });
  streamModeOpenedContainers = [];
  // Same re-apply as on entry above, now snapping back to whatever
  // normal/fullscreen already had stored -- otherwise the article would
  // keep rendering at Stream-Modus's own (far larger) --font-scale value
  // after leaving, until the user pressed "+"/"-" again.
  setFontScale(getFontScale());
  updateFontButtonState();
}

// A currently-open table-row popover (Feature 3) can be put into
// Stream-Modus INSTEAD of the article behind it (Nutzerwunsch 2026-08-05:
// "wenn ich dann Strg+Alt+W drücke, dann soll nicht das Wiki selbst, sondern
// nur das Popover in den Stream-Modus gehen, also den kompletten Client
// ausfüllen und die Schriftgröße des Stream-Modus annehmen") -- a class on
// the popover's own overlay (sized/positioned via body.popover-stream-mode
// .table-modal-overlay in site.scss) plus the same body-level class every
// other Stream-Modus font-scale function already keys off (see
// isStreamModeActive above), so getFontScale()/setFontScale() transparently
// read/write the shared Stream-Modus cookie without needing to know or care
// whether the popover or the article triggered it.
function enterPopoverStreamMode(overlay) {
  overlay.classList.add("popover-stream-mode");
  document.body.classList.add("popover-stream-mode");
  enterStreamTitle();
  enterStreamFullscreen();
  setFontScale(getFontScale());
}
function exitPopoverStreamMode(overlay) {
  if (overlay) overlay.classList.remove("popover-stream-mode");
  document.body.classList.remove("popover-stream-mode");
  exitStreamTitle();
  exitStreamFullscreen();
  // Same re-apply as everywhere else in Stream-Modus (see
  // enterArticleStreamMode above) -- snaps --font-scale back to whatever
  // normal/fullscreen already had stored now that popover-stream-mode is
  // gone from body's classes.
  setFontScale(getFontScale());
  updateFontButtonState();
}

document.addEventListener("keydown", function (e) {
  if (e.key.toLowerCase() !== "w") return;
  if (!e.ctrlKey || !e.altKey || e.shiftKey || e.metaKey) return;
  if (isStreamModeActive()) return;
  e.preventDefault();
  // A currently-open popover takes priority over the article (Nutzerwunsch
  // 2026-08-05) -- ".table-modal-overlay" is a plain DOM query, not a
  // closure reference into the popover's own IIFE further down, so this
  // works regardless of where each piece of code happens to live in the
  // file.
  const openPopover = document.querySelector(".table-modal-overlay");
  if (openPopover) {
    enterPopoverStreamMode(openPopover);
  } else {
    enterArticleStreamMode();
  }
});
// Escape exits article-level Stream-Modus -- the popover's OWN Escape
// handler (see openTablePopover further down) checks popover-stream-mode
// FIRST and exits that instead of closing the popover outright, so this
// listener explicitly stays out of the popover-stream-mode case (that
// would otherwise double-handle the same keypress via two listeners).
document.addEventListener("keydown", function (e) {
  if (e.key !== "Escape") return;
  if (document.body.classList.contains("popover-stream-mode")) return;
  if (document.body.classList.contains("stream-mode")) exitArticleStreamMode();
});

// ---- "Rollen" (Scroll Lock) autoscroll (Nutzerwunsch 2026-08-05, redesigned
// same day) ----
// Not scoped to Stream-Modus -- works everywhere, on whatever ".content"
// happens to be on screen. Two separate pieces of state:
//   - autoScrollSpeed: the scroll speed VALUE (in levels), persisted across
//     articles/sessions via cookie.
//   - autoScrollOn: whether it's actively scrolling right now, in-memory
//     only, always OFF on entering an article (see swapContent's
//     stopAutoScroll() call above) regardless of the stored speed.
// Space toggles autoScrollOn using the current autoScrollSpeed. While ON,
// ScrollLock/Shift+ScrollLock raise/lower autoScrollSpeed (reaching 0 via
// Shift+ScrollLock turns Rollen back OFF -- a speed of 0 with Rollen still
// nominally "on" would be indistinguishable from off and just confusing).
// While OFF, Shift+ScrollLock does nothing; plain ScrollLock resets
// autoScrollSpeed to level 1 and turns Rollen ON (reset-and-start). Escape
// plays no role here anymore (superseded 2026-08-05 redesign -- an earlier
// version had Escape stop the scroll, removed together with the old
// level-only design).
// "Sehr sehr langsam" for level 1, "leicht erhöht" each further level --
// AUTOSCROLL_PX_PER_SEC_PER_LEVEL is that one-level increment, applied via
// requestAnimationFrame with a real elapsed-time delta (not a fixed
// per-tick pixel count) so the actual on-screen speed stays consistent
// regardless of the display's refresh rate.
const AUTOSCROLL_PX_PER_SEC_PER_LEVEL = 6;
let autoScrollSpeed = parseInt(getCookie("autoScrollSpeed"), 10) || 0;
let autoScrollOn = false;
let autoScrollRafId = null;
let autoScrollLastTs = null;
// Sub-pixel carry between frames (Nutzerwunsch 2026-08-05 bugfix: "Erst nach
// dem sechsten Drücken setzt es sich überhaupt in Bewegung") -- element.
// scrollTop always reports/stores a whole pixel, rounding away any fraction
// the instant it's read back. At low levels the per-frame delta is well
// under 1px (level 1 = 6px/sec, ~0.1px per ~16ms frame), so doing
// "content.scrollTop += delta" directly discarded that fraction EVERY
// single frame -- it could never accumulate past a whole pixel on its own,
// which is exactly why nothing visibly moved until a high enough level made
// even a SINGLE frame's delta round up to 1px by itself (~level 6, matching
// the reported symptom). Accumulating the fractional remainder in this
// plain JS number instead (never read back from the DOM, so never rounded)
// and only flushing whole pixels to scrollTop once they add up fixes this
// for every level, including 1.
let autoScrollRemainder = 0;
function persistAutoScrollSpeed() {
  setCookie("autoScrollSpeed", String(autoScrollSpeed));
}
function autoScrollTick(ts) {
  if (!autoScrollOn) {
    autoScrollRafId = null;
    autoScrollLastTs = null;
    autoScrollRemainder = 0;
    return;
  }
  if (autoScrollLastTs === null) autoScrollLastTs = ts;
  const dt = (ts - autoScrollLastTs) / 1000;
  autoScrollLastTs = ts;
  const content = document.querySelector(".content");
  if (content) {
    autoScrollRemainder += autoScrollSpeed * AUTOSCROLL_PX_PER_SEC_PER_LEVEL * dt;
    const whole = Math.trunc(autoScrollRemainder);
    if (whole !== 0) {
      content.scrollTop += whole;
      autoScrollRemainder -= whole;
    }
  }
  autoScrollRafId = requestAnimationFrame(autoScrollTick);
}
function startAutoScroll() {
  autoScrollOn = true;
  if (autoScrollRafId === null) {
    autoScrollLastTs = null;
    autoScrollRafId = requestAnimationFrame(autoScrollTick);
  }
}
function stopAutoScroll() {
  autoScrollOn = false;
  if (autoScrollRafId !== null) {
    cancelAnimationFrame(autoScrollRafId);
    autoScrollRafId = null;
  }
  autoScrollLastTs = null;
  autoScrollRemainder = 0;
}
document.addEventListener("keydown", function (e) {
  if (e.key !== "ScrollLock") return;
  const active = document.activeElement;
  if (active && (active.tagName === "INPUT" || active.tagName === "TEXTAREA" || active.isContentEditable)) return;
  e.preventDefault();
  if (!autoScrollOn) {
    if (e.shiftKey) return; // Shift+Rollen while OFF does nothing
    autoScrollSpeed = 1;
    startAutoScroll();
  } else if (e.shiftKey) {
    autoScrollSpeed = Math.max(0, autoScrollSpeed - 1);
    if (autoScrollSpeed === 0) stopAutoScroll();
  } else {
    autoScrollSpeed += 1;
  }
  persistAutoScrollSpeed();
});
document.addEventListener("keydown", function (e) {
  if (e.key !== " " && e.code !== "Space") return;
  const active = document.activeElement;
  if (active && (active.tagName === "INPUT" || active.tagName === "TEXTAREA" || active.tagName === "SELECT" || active.tagName === "BUTTON" || active.isContentEditable)) return;
  e.preventDefault();
  if (autoScrollOn) {
    stopAutoScroll();
  } else {
    startAutoScroll();
  }
});

// ---- Skills overview filter (Nutzerwunsch 2026-07-31, Genesys page only --
// see buildSkillsOverviewHtml in build-site.js) ----
// Delegated on "document" rather than queried once at load: this page (like
// any other) can be reached via the SPA client-side navigate() above, which
// only swaps main.content's innerHTML -- a listener bound directly to
// elements present at initial script-load time would miss controls that
// arrive later via a swap.
function applySkillsFilter(root) {
  const select = root.querySelector(".skills-setting-select");
  const magicBox = root.querySelector(".skills-magic-checkbox");
  const table = root.querySelector(".overview-table");
  if (!select || !magicBox || !table) return;
  const setting = select.value;
  const magicOn = magicBox.checked;
  table.querySelectorAll("tbody tr").forEach(function (tr) {
    const visible = tr.dataset.magic === "1"
      ? magicOn
      : (tr.dataset.settings || "").split("|").some((s) => s === "All" || s === setting);
    tr.hidden = !visible;
  });
}
document.addEventListener("change", function (e) {
  const root = e.target.closest(".skills-overview");
  if (!root) return;
  if (e.target.classList.contains("skills-setting-select")) {
    // Changing the Setting always resets Magic Rules to its setting-specific
    // default (checked for Fantasy, unchecked otherwise) -- Nutzerwunsch
    // 2026-07-31, an explicit override of whatever the checkbox was set to.
    const magicBox = root.querySelector(".skills-magic-checkbox");
    if (magicBox) magicBox.checked = e.target.value === "Fantasy";
  }
  if (e.target.classList.contains("skills-setting-select") || e.target.classList.contains("skills-magic-checkbox")) {
    applySkillsFilter(root);
  }
});

// REMOVED 2026-08-04 (Nutzerwunsch, emphatic): a click anywhere in a table
// row used to navigate the same as clicking its own name link. No longer --
// "auf einer Zelle soll nicht mehr einem etwaigen Link gefolgt werden, nur
// bei Texten, die Links sind" -- clicking a cell now does nothing unless the
// click actually lands on the link text itself, which the browser's own
// native <a> behavior (and the SPA nav handler above) already covers with
// no extra JS needed here.

// Sortable column headers -- overview tables originally (Nutzerwunsch
// 2026-07-31: Skills' Name/Characteristic/Group; Talents' Name/Tier/
// Activation/Ranked -- Page and Description are always plain), generalized
// 2026-08-04 to arbitrary book tables too (see TABLE_FEATURES/
// applyTableSortable in build-site.js -- same class="sortable"/data-sort/
// .sort-indicator shape either way, so this one handler already covers
// both; only the selector itself needed broadening from ".overview-table
// th.sortable" to a plain "th.sortable"). Clicking a sortable column cycles
// that column asc -> desc -> off. Only one column is ever active at a time
// -- clicking a different header always starts it fresh at "asc" and resets
// the rest. "off" restores the table's original source order via each row's
// own data-idx, set at build time (see buildOverviewTableHead/
// buildSkillsOverviewHtml/buildTalentsOverviewHtml/applyTableSortable).
document.addEventListener("click", function (e) {
  const th = e.target.closest("th.sortable");
  if (!th) return;
  const headerCells = Array.from(th.parentElement.children);
  const next = th.dataset.sort === "asc" ? "desc" : th.dataset.sort === "desc" ? "" : "asc";
  headerCells.forEach(function (h) {
    const active = h === th;
    h.dataset.sort = active ? next : "";
    const indicator = h.querySelector(".sort-indicator");
    if (indicator) indicator.textContent = active ? (next === "asc" ? " ▴" : next === "desc" ? " ▾" : "") : "";
  });
  const table = th.closest("table");
  const tbody = table.querySelector("tbody");
  const colIndex = headerCells.indexOf(th);
  const rows = Array.from(tbody.querySelectorAll("tr"));
  rows.sort(function (a, b) {
    if (next === "") return Number(a.dataset.idx) - Number(b.dataset.idx);
    const av = a.children[colIndex].textContent.trim().toLowerCase();
    const bv = b.children[colIndex].textContent.trim().toLowerCase();
    if (av === bv) return Number(a.dataset.idx) - Number(b.dataset.idx);
    const cmp = av < bv ? -1 : 1;
    return next === "asc" ? cmp : -cmp;
  });
  rows.forEach(function (r) { tbody.appendChild(r); });
  // Table II.1–1's grouping rows (see TABLE_GROUP_ROWS_HIDE_ON_SORT/
  // markTableGroupRows in build-site.js) hide themselves the instant ANY
  // column in this table is actively sorted, and reappear once every column
  // is back to "off" (Nutzerwunsch 2026-08-04) -- a sorted view mixes rows
  // from every group together, so a row that used to introduce "Melee
  // Weapons" no longer sits above only melee weapons.
  const anySortActive = Array.from(table.querySelectorAll("th.sortable")).some(function (h) { return h.dataset.sort; });
  table.querySelectorAll(".table-group-row").forEach(function (row) {
    row.hidden = anySortActive;
  });
});

// Feature 3, Popover (Nutzerwunsch 2026-08-04, see applyTableDblclick in
// build-site.js): a table opts in via data-dblclick-title on its own
// <table> tag (only present when the user's per-table config named a
// trigger column AND that column's header actually exists). Opens a modal
// listing every column:value pair for the clicked row (the trigger column
// shows up as just another ordinary row -- it only decides whether the
// feature exists, it isn't singled out in the popover itself). Never on a
// click that lands on a link, which still needs to navigate normally.
(function () {
  function escapeHtml(s) {
    return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  // Case-sensitive small caps (Nutzerwunsch 2026-08-04: "jeder Anfangs-
  // buchstabe groß, Rest klein. AUSNAHME: wenn kein Vokal drin vorkommt:
  // alles groß. Wenn Ziffern drin vorkommen: alles groß.") -- paired with
  // .table-modal-label's own "font-variant: small-caps" in site.scss, which
  // only shrinks LOWERCASE letters, so an all-caps exception label (no CSS
  // branch needed for it) renders as plain full-height caps automatically.
  // "\d"/"\w" (doubled), not "d"/"w" -- same template-literal
  // backslash-eating landmine as stripLinksForPopover below: a single ""
  // before a non-special character is not a recognized string escape and
  // gets silently dropped when this outer template literal is evaluated
  // ( is even worse -- it IS a recognized escape, for a literal backspace
  // control character, which is what a single "" here would have produced
  // instead of a word-boundary assertion). Doubling makes a single real
  // backslash survive into the generated nav.js.
  // REGRESS 2026-08-04 fix: a header like "{Tr}"/"{Th}" (see DICE_MAP/
  // RESULT_MAP in build-site.js -- these are case-sensitive notation tokens
  // the glyph-rendering pass looks up verbatim) has no vowel, so the
  // ALL-CAPS exception below used to mistake it for an abbreviation like
  // "HP" and corrupt it to "{TR}"/"{TH}", silently breaking the symbol.
  // Notation tokens are pulled out to a placeholder BEFORE the case logic
  // runs (and are excluded from the vowel/digit exception check that logic
  // does), then spliced back in completely untouched. w (ASCII-only in a
  // non-unicode regex) doesn't match the placeholder character either, so
  // the title-case .replace below skips over it on its own.
  function popoverHeaderCase(text) {
    const tokens = [];
    const placeholder = text.replace(/\{[^}]*\}|\[[^\]]*\]/g, function (m) { tokens.push(m); return "\uE000"; });
    const cased = (!/[aeiouAEIOU]/.test(placeholder) || /\d/.test(placeholder))
      ? placeholder.toUpperCase()
      : placeholder.replace(/\w+/g, function (w) { return w.charAt(0).toUpperCase() + w.slice(1).toLowerCase(); });
    let i = 0;
    return cased.replace(/\uE000/g, function () { return tokens[i++]; });
  }

  // A header's plain label text, with its (possibly non-empty, if a sort is
  // currently active -- see the sortable-column handler above) .sort-
  // indicator span excluded, via a detached clone rather than a regex so it
  // doesn't depend on the indicator's exact glyph/markup.
  function headerLabelText(th) {
    const clone = th.cloneNode(true);
    const indicator = clone.querySelector(".sort-indicator");
    if (indicator) indicator.remove();
    return clone.textContent.trim();
  }

  // Popover entries are plain display text, never clickable (Nutzerwunsch
  // 2026-08-04: "die Einträge in einem Popover sollen keine Links sein") --
  // strips any <a ...>/</a> wrapper a cell's HTML carries (e.g. a Name
  // column linking to its own article, or an Item Quality chevron-link)
  // while keeping whatever's inside (text, glyph icons, etc.).
  function stripLinksForPopover(html) {
    // NAV_JS is itself a JS template-literal string in build-site.js -- a
    // single backslash before a non-special character (like "/") is not a
    // recognized string escape and gets silently dropped when the template
    // literal is evaluated, so "/" here must be doubled to "\/" to survive
    // into the generated nav.js as an actual single backslash (see the
    // sort-indicator regex further up for the same landmine, now avoided
    // there entirely by using cloneNode instead of a regex).
    return html.replace(/<a\b[^>]*>/g, "").replace(/<\/a>/g, "");
  }

  const COPY_ICON_SVG = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" ' +
    'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
    '<rect x="9" y="9" width="12" height="12" rx="2"></rect>' +
    '<path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path></svg>';

  function openTablePopover(e) {
    if (e.target.closest("a")) return;
    const tr = e.target.closest("tbody tr");
    if (!tr || tr.classList.contains("table-group-row")) return;
    const table = tr.closest("table");
    if (!table || !table.dataset.dblclickTitle) return;
    const headerCells = Array.from(table.querySelectorAll("thead th"));
    const cells = Array.from(tr.children);
    if (!cells.length) return;

    // Stream-Modus popover column rules (Nutzerwunsch 2026-08-05, see
    // POPOVER_HIDE_TITLE_COLS/POPOVER_HIDE_COLS in build-site.js, which
    // stamps these as comma-separated data attributes at build time) --
    // "Spaltentitel 'X' weg": only X's header/label is hidden, its value
    // stays and spans the full row width. "Spalte 'X' weg": both header AND
    // value are hidden entirely. Column names matched case-insensitively
    // against each <th>'s own plain label text.
    function parseColList(attr) {
      return attr ? attr.split(",").map(function (s) { return s.trim().toLowerCase(); }).filter(Boolean) : [];
    }
    const hideTitleCols = parseColList(table.dataset.popoverHideTitleCols);
    const hideCols = parseColList(table.dataset.popoverHideCols);
    function findCellByHeaderName(name) {
      if (!name) return null;
      const lower = name.trim().toLowerCase();
      const idx = headerCells.findIndex(function (th) { return headerLabelText(th).trim().toLowerCase() === lower; });
      return idx >= 0 ? cells[idx] : null;
    }

    let rowsHtml = "";
    const clipboardLines = [];
    headerCells.forEach(function (th, i) {
      const cell = cells[i];
      if (!cell) return;
      const headerName = headerLabelText(th).trim().toLowerCase();
      const isHiddenCol = hideCols.indexOf(headerName) !== -1;
      const isHiddenTitleOnly = !isHiddenCol && hideTitleCols.indexOf(headerName) !== -1;
      const label = popoverHeaderCase(headerLabelText(th));
      const labelClass = "table-modal-label" + (isHiddenCol || isHiddenTitleOnly ? " table-modal-cell-hidden" : "");
      const valueClass = "table-modal-value" +
        (isHiddenCol ? " table-modal-cell-hidden" : "") +
        (isHiddenTitleOnly ? " table-modal-value-full" : "");
      rowsHtml += '<span class="' + labelClass + '">' + escapeHtml(label) + '</span>' +
        '<span class="' + valueClass + '">' + stripLinksForPopover(cell.innerHTML) + '</span>';
      if (!isHiddenCol) clipboardLines.push(label + ": " + cell.textContent.trim());
    });

    // Popover title, with the two per-row title-rewrite rules layered on top
    // of the plain data-dblclick-title (Nutzerwunsch 2026-08-05):
    // data-popover-title-replace-col substitutes that column's OWN value in
    // place of the title's pre-baked brace-prefix/-suffix split (the
    // "Result Options" rule -- see computeDblclickTitleBraceSplit in
    // build-site.js); data-popover-title-append-col appends ": " + that
    // column's value straight onto the SAME title string (GC I.6-10's D100),
    // which is what makes it inherit the title's own font/color/size --
    // it's the exact same <h3>, no separate styled element involved.
    let titleHtml = table.dataset.dblclickTitle;
    if (table.dataset.popoverTitleReplaceCol) {
      const cell = findCellByHeaderName(table.dataset.popoverTitleReplaceCol);
      if (cell) {
        // Fixed single space on each side, not whatever the build-time
        // split happened to trim off (build-site.js's own prefix/suffix
        // extraction trims BOTH ends of each half, since it has no reliable
        // way to know how much of the original whitespace belonged at the
        // cut point) -- every known use of this rule has the same "TEXT
        // {notation} TEXT" shape, so a plain single space reads correctly
        // on both sides regardless.
        const prefix = table.dataset.popoverTitleBracePrefix || "";
        const suffix = table.dataset.popoverTitleBraceSuffix || "";
        titleHtml = (prefix ? prefix + " " : "") +
          stripLinksForPopover(cell.innerHTML) +
          (suffix ? " " + suffix : "");
      }
    }
    if (table.dataset.popoverTitleAppendCol) {
      const cell = findCellByHeaderName(table.dataset.popoverTitleAppendCol);
      if (cell) titleHtml = titleHtml + ": " + stripLinksForPopover(cell.innerHTML);
    }

    const overlay = document.createElement("div");
    overlay.className = "table-modal-overlay";
    overlay.innerHTML = '<div class="table-modal" role="dialog" aria-modal="true">' +
      '<div class="table-modal-header">' +
      '<h3 class="table-modal-title">' + titleHtml + '</h3>' +
      '<button type="button" class="table-modal-copy" title="Copy values to clipboard" aria-label="Copy values to clipboard">' + COPY_ICON_SVG + '</button>' +
      '</div>' +
      '<div class="table-modal-rows">' + rowsHtml + '</div>' +
      '</div>';
    document.body.appendChild(overlay);
    function closeModal() {
      // Belt-and-suspenders cleanup (Nutzerwunsch 2026-08-05 feature): a
      // stream-mode popover is normally only ever closed via its own Escape
      // branch above (which exits stream mode WITHOUT closing), but an
      // outside click still reaches this function directly -- without this,
      // that would remove the overlay while leaving body.popover-stream-mode
      // and the swapped window title stuck behind for good.
      if (overlay.classList.contains("popover-stream-mode")) exitPopoverStreamMode(overlay);
      overlay.remove();
      document.removeEventListener("keydown", onKeydown);
    }
    function onKeydown(ev) {
      if (ev.key !== "Escape") return;
      // Popover-level Stream-Modus (Nutzerwunsch 2026-08-05) intercepts
      // Escape FIRST -- exits Stream-Modus only, leaves the popover itself
      // open, exactly mirroring how Escape behaves for the article-level
      // Stream-Modus (see the global keydown listener further up: it
      // explicitly stays out of this case for the same reason, so only ONE
      // of the two ever actually handles a given Escape press).
      if (overlay.classList.contains("popover-stream-mode")) {
        exitPopoverStreamMode(overlay);
        return;
      }
      closeModal();
    }
    // Outside click (anywhere on the overlay backdrop, i.e. not inside
    // .table-modal itself) closes it -- the only way to close it now that
    // the X button is gone (Nutzerwunsch 2026-08-04).
    overlay.addEventListener("click", function (ev) {
      if (ev.target === overlay) closeModal();
    });
    overlay.querySelector(".table-modal-copy").addEventListener("click", function () {
      navigator.clipboard.writeText(clipboardLines.join("\n"));
    });
    document.addEventListener("keydown", onKeydown);
  }

  // Trigger: double-click/double-tap ONLY (Nutzerwunsch 2026-08-05,
  // reverting the 2026-08-04 "single click on mouse, double tap on touch"
  // hybrid: "es wird NICHT MEHR per einfachem Klick, sondern wieder nur per
  // Doppelklick ausgeführt") -- a single plain "dblclick" listener now
  // covers both input types, since a double TAP on touch already synthesizes
  // a real "dblclick" event on its own, no separate touch-path needed.
  document.addEventListener("dblclick", openTablePopover);

  // Mennara map hover (Nutzerwunsch 2026-08-07): a delegated listener on
  // document, not bound per-element, so it survives SPA content swaps
  // untouched (same reasoning as the dblclick listener just above) -- the
  // map's own markup only ever needs a data-region attribute, no rebinding
  // after navigation. Every element carrying data-region inside .mennara-map
  // is EITHER a (permanently invisible) Trigger hit-zone OR the visible
  // text-label path for that same region (see buildMennaraMapHtml in
  // build-site.js) -- hovering either one highlights the label(s) sharing
  // its region key, since the Trigger's padded shape is what makes "just
  // getting close" already count, while still working if the mouse happens
  // to land on the visible text itself.
  document.addEventListener("mouseover", function (e) {
    const src = e.target.closest(".mennara-map [data-region]");
    if (!src) return;
    document.querySelectorAll('.mennara-map .mennara-region-label[data-region="' + src.dataset.region + '"]').forEach(function (el) {
      el.classList.add("region-active");
    });
  });
  document.addEventListener("mouseout", function (e) {
    const src = e.target.closest(".mennara-map [data-region]");
    if (!src || src.contains(e.relatedTarget)) return;
    document.querySelectorAll('.mennara-map .mennara-region-label[data-region="' + src.dataset.region + '"]').forEach(function (el) {
      el.classList.remove("region-active");
    });
  });

  // Mennara map scroll-wheel zoom + drag-to-pan (Nutzerwunsch 2026-08-07).
  // Manipulates the <svg>'s own viewBox directly rather than a CSS transform
  // -- the box's rendered CSS size (from site.scss's max-width/max-height
  // fit-to-container rule) stays constant throughout, since width and height
  // are always scaled by the exact same factor, so the aspect ratio (and
  // therefore the fitted CSS size) never changes; only which portion of the
  // map is visible does. The original viewBox is cached on the element itself
  // (data-base-viewbox, lazily on first interaction) as the fixed reference
  // for clamping -- panning/zooming can never reveal empty space beyond the
  // map's own extent, and zooming out bottoms out at the original full view.
  function mennaraBaseViewBox(svg) {
    if (!svg.dataset.baseViewbox) svg.dataset.baseViewbox = svg.getAttribute("viewBox");
    // "\s" (doubled), not "s" -- same template-literal backslash-eating
    // gotcha as computeDblclickTitle's "\d"/"\w" elsewhere in this file.
    return svg.dataset.baseViewbox.split(/\s+/).map(Number);
  }
  document.addEventListener("wheel", function (e) {
    const svg = e.target.closest(".mennara-map svg");
    if (!svg) return;
    e.preventDefault();
    const [, , baseW, baseH] = mennaraBaseViewBox(svg);
    const vb = svg.viewBox.baseVal;
    const rect = svg.getBoundingClientRect();
    // Cursor position as a fraction of the rendered box, then the point in
    // current SVG user-space it sits over -- the zoom-to-cursor formula
    // below re-derives x/y so that exact user-space point stays under the
    // cursor after the resize, instead of the view just scaling around its
    // own center.
    const fx = (e.clientX - rect.left) / rect.width;
    const fy = (e.clientY - rect.top) / rect.height;
    const svgX = vb.x + fx * vb.width;
    const svgY = vb.y + fy * vb.height;
    const factor = e.deltaY < 0 ? 1 / 1.1 : 1.1;
    const newW = Math.min(baseW, Math.max(baseW / 8, vb.width * factor));
    const newH = Math.min(baseH, Math.max(baseH / 8, vb.height * factor));
    const newX = Math.min(baseW - newW, Math.max(0, svgX - fx * newW));
    const newY = Math.min(baseH - newH, Math.max(0, svgY - fy * newH));
    svg.setAttribute("viewBox", [newX, newY, newW, newH].join(" "));
  }, { passive: false });

  let mennaraDrag = null;
  document.addEventListener("mousedown", function (e) {
    const svg = e.target.closest(".mennara-map svg");
    if (!svg || e.button !== 0) return;
    const [, , baseW, baseH] = mennaraBaseViewBox(svg);
    const vb = svg.viewBox.baseVal;
    mennaraDrag = { svg, baseW, baseH, startClientX: e.clientX, startClientY: e.clientY, startX: vb.x, startY: vb.y, w: vb.width, h: vb.height, moved: false };
    svg.closest(".mennara-map").classList.add("is-grabbing");
  });
  document.addEventListener("mousemove", function (e) {
    if (!mennaraDrag) return;
    const dxClient = e.clientX - mennaraDrag.startClientX;
    const dyClient = e.clientY - mennaraDrag.startClientY;
    // Small-movement threshold (Nutzerwunsch-independent, same "was this
    // actually a drag" guard the fullscreen page-swipe code elsewhere in
    // this file already uses) -- below it, the upcoming mouseup is still
    // treated as a plain click (region navigation), not a pan.
    if (Math.abs(dxClient) > 3 || Math.abs(dyClient) > 3) mennaraDrag.moved = true;
    if (!mennaraDrag.moved) return;
    const rect = mennaraDrag.svg.getBoundingClientRect();
    const newX = Math.min(mennaraDrag.baseW - mennaraDrag.w, Math.max(0, mennaraDrag.startX - dxClient * (mennaraDrag.w / rect.width)));
    const newY = Math.min(mennaraDrag.baseH - mennaraDrag.h, Math.max(0, mennaraDrag.startY - dyClient * (mennaraDrag.h / rect.height)));
    mennaraDrag.svg.setAttribute("viewBox", [newX, newY, mennaraDrag.w, mennaraDrag.h].join(" "));
  });
  document.addEventListener("mouseup", function () {
    if (!mennaraDrag) return;
    mennaraDrag.svg.closest(".mennara-map").classList.remove("is-grabbing");
    if (mennaraDrag.moved) {
      // Swallow the click a real drag-release still fires, one-shot capture
      // listener ahead of the site's own bubbling <a> click interceptor
      // further up -- otherwise releasing a drag over a Trigger would also
      // navigate, which a plain pan was never meant to do.
      const guard = function (ev) { ev.stopPropagation(); ev.preventDefault(); document.removeEventListener("click", guard, true); };
      document.addEventListener("click", guard, true);
    }
    mennaraDrag = null;
  });
})();
